use incin::prelude::*;

fn main() -> Result<()> {
    let a = Cpu.ones(shape![2, 2])?.require_grad();
    let b = Cpu.full(shape![2, 2], 3.0)?;

    let c = &a * &b;
    let loss = c.sum_all()?;

    let grads = loss.backward()?;
    let grad_a = grads
        .require(&a)?
        .to_vec1::<f32>()?;

    println!("d(loss)/d(a) = {:?}", grad_a);
    Ok(())
}

